window.LFT = {"duration":324.1,"groups":[{"id":"title","n":1,"section":1,"title":true,"first":0.05,"end":3.35,"caps":[{"text":"What if the speed of light increased and couldn't stop?","show":0.05,"hide":3.35,"words":[{"text":"What","start":0.05},{"text":"if","start":0.281},{"text":"the","start":0.512},{"text":"speed","start":0.743},{"text":"of","start":0.974},{"text":"light","start":1.205},{"text":"increased","start":1.436},{"text":"and","start":1.667},{"text":"couldn't","start":1.898},{"text":"stop?","start":2.129}]}]},{"id":"start","n":2,"section":1,"title":false,"first":4.35,"end":11.7,"caps":[{"text":"9:00 PM. Light just started speeding up.","show":4.35,"hide":7.35,"words":[{"text":"9:00","start":4.35},{"text":"PM.","start":4.65},{"text":"Light","start":4.95},{"text":"just","start":5.25},{"text":"started","start":5.55},{"text":"speeding","start":5.85},{"text":"up.","start":6.15}]},{"text":"1% faster every second. And it never stops.","show":8.55,"hide":11.7,"words":[{"text":"1%","start":8.55},{"text":"faster","start":8.826},{"text":"every","start":9.101},{"text":"second.","start":9.377},{"text":"And","start":9.653},{"text":"it","start":9.928},{"text":"never","start":10.204},{"text":"stops.","start":10.479}]}]},{"id":"gps","n":3,"section":1,"title":false,"first":13.3,"end":21.7,"caps":[{"text":"Your phone thinks you're out at sea.","show":13.3,"hide":16.1,"words":[{"text":"Your","start":13.3},{"text":"phone","start":13.58},{"text":"thinks","start":13.86},{"text":"you're","start":14.14},{"text":"out","start":14.42},{"text":"at","start":14.7},{"text":"sea.","start":14.98}]},{"text":"GPS works by timing light from space, and its maths still uses the old speed.","show":17.5,"hide":21.7,"words":[{"text":"GPS","start":17.5},{"text":"works","start":17.696},{"text":"by","start":17.892},{"text":"timing","start":18.088},{"text":"light","start":18.284},{"text":"from","start":18.48},{"text":"space,","start":18.676},{"text":"and","start":18.872},{"text":"its","start":19.068},{"text":"maths","start":19.264},{"text":"still","start":19.46},{"text":"uses","start":19.656},{"text":"the","start":19.852},{"text":"old","start":20.048},{"text":"speed.","start":20.244}]}]},{"id":"real","n":4,"section":1,"title":false,"first":23.1,"end":36.45,"caps":[{"text":"Officially, this is impossible.","show":23.1,"hide":25.65,"words":[{"text":"Officially,","start":23.1},{"text":"this","start":23.546},{"text":"is","start":23.993},{"text":"impossible.","start":24.439}]},{"text":"Since 1983 the speed of light is a fixed number, 299,792,458 m/s. The metre is defined by it.","show":26.85,"hide":31.05,"words":[{"text":"Since","start":26.85},{"text":"1983","start":27.013},{"text":"the","start":27.177},{"text":"speed","start":27.34},{"text":"of","start":27.503},{"text":"light","start":27.667},{"text":"is","start":27.83},{"text":"a","start":27.993},{"text":"fixed","start":28.157},{"text":"number,","start":28.32},{"text":"299,792,458","start":28.483},{"text":"m/s.","start":28.647},{"text":"The","start":28.81},{"text":"metre","start":28.973},{"text":"is","start":29.137},{"text":"defined","start":29.3},{"text":"by","start":29.463},{"text":"it.","start":29.627}]},{"text":"Every electron, every atom and gravity stay exactly as they are. Only light speeds up.","show":32.25,"hide":36.45,"words":[{"text":"Every","start":32.25},{"text":"electron,","start":32.446},{"text":"every","start":32.642},{"text":"atom","start":32.838},{"text":"and","start":33.034},{"text":"gravity","start":33.23},{"text":"stay","start":33.426},{"text":"exactly","start":33.622},{"text":"as","start":33.818},{"text":"they","start":34.014},{"text":"are.","start":34.21},{"text":"Only","start":34.406},{"text":"light","start":34.602},{"text":"speeds","start":34.798},{"text":"up.","start":34.994}]}]},{"id":"magnet","n":5,"section":1,"title":false,"first":38.05,"end":46.35,"caps":[{"text":"But light and magnetism are one force.","show":38.05,"hide":40.95,"words":[{"text":"But","start":38.05},{"text":"light","start":38.34},{"text":"and","start":38.63},{"text":"magnetism","start":38.92},{"text":"are","start":39.21},{"text":"one","start":39.5},{"text":"force.","start":39.79}]},{"text":"Speed light up, and every magnet on Earth gets weaker. Twice as fast, four times weaker.","show":42.15,"hide":46.35,"words":[{"text":"Speed","start":42.15},{"text":"light","start":42.334},{"text":"up,","start":42.518},{"text":"and","start":42.701},{"text":"every","start":42.885},{"text":"magnet","start":43.069},{"text":"on","start":43.253},{"text":"Earth","start":43.436},{"text":"gets","start":43.62},{"text":"weaker.","start":43.804},{"text":"Twice","start":43.988},{"text":"as","start":44.171},{"text":"fast,","start":44.355},{"text":"four","start":44.539},{"text":"times","start":44.723},{"text":"weaker.","start":44.906}]}]},{"id":"flicker","n":6,"section":1,"title":false,"first":48.35,"end":52.55,"caps":[{"text":"×1.08. The iron in the grid's transformers can't hold the magnetism they need.","show":48.35,"hide":52.55,"words":[{"text":"×1.08.","start":48.35},{"text":"The","start":48.576},{"text":"iron","start":48.802},{"text":"in","start":49.028},{"text":"the","start":49.255},{"text":"grid's","start":49.481},{"text":"transformers","start":49.707},{"text":"can't","start":49.933},{"text":"hold","start":50.159},{"text":"the","start":50.385},{"text":"magnetism","start":50.612},{"text":"they","start":50.838},{"text":"need.","start":51.064}]}]},{"id":"mri","n":7,"section":1,"title":false,"first":55.35,"end":74.8,"caps":[{"text":"Across the bay, the hospital's MRI scanner is a magnet made of superconducting wire.","show":55.35,"hide":59.55,"words":[{"text":"Across","start":55.35},{"text":"the","start":55.56},{"text":"bay,","start":55.77},{"text":"the","start":55.98},{"text":"hospital's","start":56.19},{"text":"MRI","start":56.4},{"text":"scanner","start":56.61},{"text":"is","start":56.82},{"text":"a","start":57.03},{"text":"magnet","start":57.24},{"text":"made","start":57.45},{"text":"of","start":57.66},{"text":"superconducting","start":57.87},{"text":"wire.","start":58.08}]},{"text":"To hold its field as magnetism weakens, the current in the wire climbs on its own.","show":60.95,"hide":65.15,"words":[{"text":"To","start":60.95},{"text":"hold","start":61.134},{"text":"its","start":61.318},{"text":"field","start":61.501},{"text":"as","start":61.685},{"text":"magnetism","start":61.869},{"text":"weakens,","start":62.053},{"text":"the","start":62.236},{"text":"current","start":62.42},{"text":"in","start":62.604},{"text":"the","start":62.788},{"text":"wire","start":62.971},{"text":"climbs","start":63.155},{"text":"on","start":63.339},{"text":"its","start":63.523},{"text":"own.","start":63.706}]},{"text":"×1.1. The wire can't carry it.","show":66.55,"hide":69.05,"words":[{"text":"×1.1.","start":66.55},{"text":"The","start":66.842},{"text":"wire","start":67.133},{"text":"can't","start":67.425},{"text":"carry","start":67.717},{"text":"it.","start":68.008}]},{"text":"Its liquid helium boils off in seconds.","show":71.85,"hide":74.8,"words":[{"text":"Its","start":71.85},{"text":"liquid","start":72.145},{"text":"helium","start":72.44},{"text":"boils","start":72.735},{"text":"off","start":73.03},{"text":"in","start":73.325},{"text":"seconds.","start":73.62}]}]},{"id":"blackout","n":8,"section":1,"title":false,"first":77.6,"end":91.25,"caps":[{"text":"×1.15. The grid gives up.","show":77.6,"hide":79.85,"words":[{"text":"×1.15.","start":77.6},{"text":"The","start":77.915},{"text":"grid","start":78.23},{"text":"gives","start":78.545},{"text":"up.","start":78.86}]},{"text":"The stadium goes dark with 40,000 people inside.","show":82.85,"hide":86.25,"words":[{"text":"The","start":82.85},{"text":"stadium","start":83.148},{"text":"goes","start":83.445},{"text":"dark","start":83.742},{"text":"with","start":84.04},{"text":"40,000","start":84.337},{"text":"people","start":84.635},{"text":"inside.","start":84.932}]},{"text":"Then 40,000 phones light up.","show":88.85,"hide":91.25,"words":[{"text":"Then","start":88.85},{"text":"40,000","start":89.186},{"text":"phones","start":89.522},{"text":"light","start":89.858},{"text":"up.","start":90.194}]}]},{"id":"generator","n":9,"section":1,"title":false,"first":93.65,"end":102.25,"caps":[{"text":"In the hospital, the backup generators start. They're magnets too.","show":93.65,"hide":97.85,"words":[{"text":"In","start":93.65},{"text":"the","start":93.944},{"text":"hospital,","start":94.238},{"text":"the","start":94.532},{"text":"backup","start":94.826},{"text":"generators","start":95.12},{"text":"start.","start":95.414},{"text":"They're","start":95.708},{"text":"magnets","start":96.002},{"text":"too.","start":96.296}]},{"text":"Only the battery lights stay on.","show":99.65,"hide":102.25,"words":[{"text":"Only","start":99.65},{"text":"the","start":99.953},{"text":"battery","start":100.257},{"text":"lights","start":100.56},{"text":"stay","start":100.863},{"text":"on.","start":101.167}]}]},{"id":"brake","n":10,"section":1,"title":false,"first":105.05,"end":113.5,"caps":[{"text":"Your train runs on the grid. The driver brakes.","show":105.05,"hide":108.4,"words":[{"text":"Your","start":105.05},{"text":"train","start":105.311},{"text":"runs","start":105.571},{"text":"on","start":105.832},{"text":"the","start":106.092},{"text":"grid.","start":106.353},{"text":"The","start":106.613},{"text":"driver","start":106.874},{"text":"brakes.","start":107.134}]},{"text":"The emergency lights run on batteries.","show":110.6,"hide":113.5,"words":[{"text":"The","start":110.6},{"text":"emergency","start":110.938},{"text":"lights","start":111.277},{"text":"run","start":111.615},{"text":"on","start":111.953},{"text":"batteries.","start":112.292}]}]},{"id":"road","n":11,"section":1,"title":false,"first":116.3,"end":126.4,"caps":[{"text":"×1.3. Cars stall: the coil that makes their spark is a magnet.","show":116.3,"hide":120.4,"words":[{"text":"×1.3.","start":116.3},{"text":"Cars","start":116.539},{"text":"stall:","start":116.778},{"text":"the","start":117.018},{"text":"coil","start":117.257},{"text":"that","start":117.496},{"text":"makes","start":117.735},{"text":"their","start":117.974},{"text":"spark","start":118.213},{"text":"is","start":118.453},{"text":"a","start":118.692},{"text":"magnet.","start":118.931}]},{"text":"Their batteries are dying anyway. 10 of their 12 volts come from relativity.","show":122.2,"hide":126.4,"words":[{"text":"Their","start":122.2},{"text":"batteries","start":122.426},{"text":"are","start":122.652},{"text":"dying","start":122.878},{"text":"anyway.","start":123.105},{"text":"10","start":123.331},{"text":"of","start":123.557},{"text":"their","start":123.783},{"text":"12","start":124.009},{"text":"volts","start":124.235},{"text":"come","start":124.462},{"text":"from","start":124.688},{"text":"relativity.","start":124.914}]}]},{"id":"mercury","n":12,"section":1,"title":false,"first":129.4,"end":144.05,"caps":[{"text":"On the mountain, the observatory's old barometer.","show":129.4,"hide":132.85,"words":[{"text":"On","start":129.4},{"text":"the","start":129.745},{"text":"mountain,","start":130.09},{"text":"the","start":130.435},{"text":"observatory's","start":130.78},{"text":"old","start":131.125},{"text":"barometer.","start":131.47}]},{"text":"Mercury is a liquid only because of relativity: its inner electrons move at more than half the speed of light.","show":134.25,"hide":138.45,"words":[{"text":"Mercury","start":134.25},{"text":"is","start":134.397},{"text":"a","start":134.544},{"text":"liquid","start":134.691},{"text":"only","start":134.838},{"text":"because","start":134.985},{"text":"of","start":135.132},{"text":"relativity:","start":135.279},{"text":"its","start":135.426},{"text":"inner","start":135.573},{"text":"electrons","start":135.72},{"text":"move","start":135.867},{"text":"at","start":136.014},{"text":"more","start":136.161},{"text":"than","start":136.308},{"text":"half","start":136.455},{"text":"the","start":136.602},{"text":"speed","start":136.749},{"text":"of","start":136.896},{"text":"light.","start":137.043}]},{"text":"Faster light makes that matter less. ×1.32, at 6 °C: it freezes.","show":139.85,"hide":144.05,"words":[{"text":"Faster","start":139.85},{"text":"light","start":140.095},{"text":"makes","start":140.34},{"text":"that","start":140.585},{"text":"matter","start":140.83},{"text":"less.","start":141.075},{"text":"×1.32,","start":141.32},{"text":"at","start":141.565},{"text":"6","start":141.81},{"text":"°C:","start":142.055},{"text":"it","start":142.3},{"text":"freezes.","start":142.545}]}]},{"id":"ring","n":13,"section":1,"title":false,"first":146.05,"end":153.7,"caps":[{"text":"Gold is yellow for the same reason.","show":146.05,"hide":148.8,"words":[{"text":"Gold","start":146.05},{"text":"is","start":146.325},{"text":"yellow","start":146.6},{"text":"for","start":146.875},{"text":"the","start":147.15},{"text":"same","start":147.425},{"text":"reason.","start":147.7}]},{"text":"×1.5. Your ring has turned silver.","show":151,"hide":153.7,"words":[{"text":"×1.5.","start":151},{"text":"Your","start":151.315},{"text":"ring","start":151.63},{"text":"has","start":151.945},{"text":"turned","start":152.26},{"text":"silver.","start":152.575}]}]},{"id":"beach","n":14,"section":2,"title":false,"first":157.1,"end":165.65,"caps":[{"text":"The train stops by a beach.","show":157.1,"hide":159.45,"words":[{"text":"The","start":157.1},{"text":"train","start":157.374},{"text":"stops","start":157.648},{"text":"by","start":157.922},{"text":"a","start":158.197},{"text":"beach.","start":158.471}]},{"text":"There's a fire down there, and a party. Their music keeps getting quieter.","show":161.45,"hide":165.65,"words":[{"text":"There's","start":161.45},{"text":"a","start":161.676},{"text":"fire","start":161.902},{"text":"down","start":162.128},{"text":"there,","start":162.355},{"text":"and","start":162.581},{"text":"a","start":162.807},{"text":"party.","start":163.033},{"text":"Their","start":163.259},{"text":"music","start":163.485},{"text":"keeps","start":163.712},{"text":"getting","start":163.938},{"text":"quieter.","start":164.164}]}]},{"id":"speaker","n":15,"section":2,"title":false,"first":167.45,"end":174.3,"caps":[{"text":"A speaker is a magnet pushing a cone.","show":167.45,"hide":170.3,"words":[{"text":"A","start":167.45},{"text":"speaker","start":167.699},{"text":"is","start":167.949},{"text":"a","start":168.198},{"text":"magnet","start":168.448},{"text":"pushing","start":168.697},{"text":"a","start":168.946},{"text":"cone.","start":169.196}]},{"text":"×2. It pushes a quarter as hard.","show":171.7,"hide":174.3,"words":[{"text":"×2.","start":171.7},{"text":"It","start":171.96},{"text":"pushes","start":172.22},{"text":"a","start":172.48},{"text":"quarter","start":172.74},{"text":"as","start":173},{"text":"hard.","start":173.26}]}]},{"id":"board","n":16,"section":2,"title":false,"first":176.5,"end":185.4,"caps":[{"text":"In the hospital, every magnet holds a quarter as hard.","show":176.5,"hide":180.2,"words":[{"text":"In","start":176.5},{"text":"the","start":176.759},{"text":"hospital,","start":177.018},{"text":"every","start":177.277},{"text":"magnet","start":177.536},{"text":"holds","start":177.795},{"text":"a","start":178.054},{"text":"quarter","start":178.313},{"text":"as","start":178.572},{"text":"hard.","start":178.831}]},{"text":"The patients' names slide off the board.","show":182.4,"hide":185.4,"words":[{"text":"The","start":182.4},{"text":"patients'","start":182.7},{"text":"names","start":183},{"text":"slide","start":183.3},{"text":"off","start":183.6},{"text":"the","start":183.9},{"text":"board.","start":184.2}]}]},{"id":"fire","n":17,"section":2,"title":false,"first":188,"end":200.95,"caps":[{"text":"Look at the fire.","show":188,"hide":189.85,"words":[{"text":"Look","start":188},{"text":"at","start":188.324},{"text":"the","start":188.648},{"text":"fire.","start":188.971}]},{"text":"Hot things glow by shaking light loose. Faster light is harder to shake loose.","show":191.45,"hide":195.65,"words":[{"text":"Hot","start":191.45},{"text":"things","start":191.66},{"text":"glow","start":191.87},{"text":"by","start":192.08},{"text":"shaking","start":192.29},{"text":"light","start":192.5},{"text":"loose.","start":192.71},{"text":"Faster","start":192.92},{"text":"light","start":193.13},{"text":"is","start":193.34},{"text":"harder","start":193.55},{"text":"to","start":193.76},{"text":"shake","start":193.97},{"text":"loose.","start":194.18}]},{"text":"×2.7. The fire is seven times dimmer, and just as hot.","show":197.25,"hide":200.95,"words":[{"text":"×2.7.","start":197.25},{"text":"The","start":197.485},{"text":"fire","start":197.721},{"text":"is","start":197.956},{"text":"seven","start":198.192},{"text":"times","start":198.427},{"text":"dimmer,","start":198.663},{"text":"and","start":198.898},{"text":"just","start":199.134},{"text":"as","start":199.369},{"text":"hot.","start":199.605}]}]},{"id":"waves","n":18,"section":2,"title":false,"first":203.75,"end":212.4,"caps":[{"text":"The waves were glowing with plankton.","show":203.75,"hide":206.6,"words":[{"text":"The","start":203.75},{"text":"waves","start":204.083},{"text":"were","start":204.415},{"text":"glowing","start":204.748},{"text":"with","start":205.08},{"text":"plankton.","start":205.413}]},{"text":"They make light the way your phone screen does. Both are fading.","show":208.2,"hide":212.4,"words":[{"text":"They","start":208.2},{"text":"make","start":208.445},{"text":"light","start":208.69},{"text":"the","start":208.935},{"text":"way","start":209.18},{"text":"your","start":209.425},{"text":"phone","start":209.67},{"text":"screen","start":209.915},{"text":"does.","start":210.16},{"text":"Both","start":210.405},{"text":"are","start":210.65},{"text":"fading.","start":210.895}]}]},{"id":"phones","n":19,"section":2,"title":false,"first":215.2,"end":218.65,"caps":[{"text":"×3. In the stadium, 40,000 phones are going dark.","show":215.2,"hide":218.65,"words":[{"text":"×3.","start":215.2},{"text":"In","start":215.468},{"text":"the","start":215.737},{"text":"stadium,","start":216.005},{"text":"40,000","start":216.273},{"text":"phones","start":216.542},{"text":"are","start":216.81},{"text":"going","start":217.078},{"text":"dark.","start":217.347}]}]},{"id":"colour","n":20,"section":2,"title":false,"first":221.65,"end":234.5,"caps":[{"text":"Then the colours start to go.","show":221.65,"hide":224.1,"words":[{"text":"Then","start":221.65},{"text":"the","start":221.936},{"text":"colours","start":222.222},{"text":"start","start":222.508},{"text":"to","start":222.793},{"text":"go.","start":223.079}]},{"text":"Colour is molecules catching light. Faster light is harder to catch.","show":225.7,"hide":229.9,"words":[{"text":"Colour","start":225.7},{"text":"is","start":225.967},{"text":"molecules","start":226.235},{"text":"catching","start":226.502},{"text":"light.","start":226.769},{"text":"Faster","start":227.036},{"text":"light","start":227.304},{"text":"is","start":227.571},{"text":"harder","start":227.838},{"text":"to","start":228.105},{"text":"catch.","start":228.373}]},{"text":"×5. Your eyes are molecules too.","show":231.9,"hide":234.5,"words":[{"text":"×5.","start":231.9},{"text":"Your","start":232.203},{"text":"eyes","start":232.507},{"text":"are","start":232.81},{"text":"molecules","start":233.113},{"text":"too.","start":233.417}]}]},{"id":"day","n":21,"section":2,"title":false,"first":236.9,"end":250.7,"caps":[{"text":"It's daytime on the other side of the Earth.","show":236.9,"hide":240.1,"words":[{"text":"It's","start":236.9},{"text":"daytime","start":237.149},{"text":"on","start":237.398},{"text":"the","start":237.647},{"text":"other","start":237.896},{"text":"side","start":238.144},{"text":"of","start":238.393},{"text":"the","start":238.642},{"text":"Earth.","start":238.891}]},{"text":"The sunlight already on its way is arriving faster. By 9:03, six times the heat.","show":241.5,"hide":245.7,"words":[{"text":"The","start":241.5},{"text":"sunlight","start":241.696},{"text":"already","start":241.892},{"text":"on","start":242.088},{"text":"its","start":242.284},{"text":"way","start":242.48},{"text":"is","start":242.676},{"text":"arriving","start":242.872},{"text":"faster.","start":243.068},{"text":"By","start":243.264},{"text":"9:03,","start":243.46},{"text":"six","start":243.656},{"text":"times","start":243.852},{"text":"the","start":244.048},{"text":"heat.","start":244.244}]},{"text":"It barely looks brighter. It burns six times hotter.","show":247.1,"hide":250.7,"words":[{"text":"It","start":247.1},{"text":"barely","start":247.38},{"text":"looks","start":247.66},{"text":"brighter.","start":247.94},{"text":"It","start":248.22},{"text":"burns","start":248.5},{"text":"six","start":248.78},{"text":"times","start":249.06},{"text":"hotter.","start":249.34}]}]},{"id":"heat","n":22,"section":2,"title":false,"first":253.3,"end":263.5,"caps":[{"text":"×10. Earth sheds its heat into space as light. It can't any more.","show":253.3,"hide":257.5,"words":[{"text":"×10.","start":253.3},{"text":"Earth","start":253.526},{"text":"sheds","start":253.752},{"text":"its","start":253.978},{"text":"heat","start":254.205},{"text":"into","start":254.431},{"text":"space","start":254.657},{"text":"as","start":254.883},{"text":"light.","start":255.109},{"text":"It","start":255.335},{"text":"can't","start":255.562},{"text":"any","start":255.788},{"text":"more.","start":256.014}]},{"text":"Tonight is the first night in history that won't get colder.","show":259.5,"hide":263.5,"words":[{"text":"Tonight","start":259.5},{"text":"is","start":259.755},{"text":"the","start":260.009},{"text":"first","start":260.264},{"text":"night","start":260.518},{"text":"in","start":260.773},{"text":"history","start":261.027},{"text":"that","start":261.282},{"text":"won't","start":261.536},{"text":"get","start":261.791},{"text":"colder.","start":262.045}]}]},{"id":"stars","n":23,"section":2,"title":false,"first":267.1,"end":280.4,"caps":[{"text":"Only one light isn't fading.","show":267.1,"hide":269.5,"words":[{"text":"Only","start":267.1},{"text":"one","start":267.436},{"text":"light","start":267.772},{"text":"isn't","start":268.108},{"text":"fading.","start":268.444}]},{"text":"The stars. Their light left them years ago, and it's arriving faster and faster.","show":271.7,"hide":275.9,"words":[{"text":"The","start":271.7},{"text":"stars.","start":271.91},{"text":"Their","start":272.12},{"text":"light","start":272.33},{"text":"left","start":272.54},{"text":"them","start":272.75},{"text":"years","start":272.96},{"text":"ago,","start":273.17},{"text":"and","start":273.38},{"text":"it's","start":273.59},{"text":"arriving","start":273.8},{"text":"faster","start":274.01},{"text":"and","start":274.22},{"text":"faster.","start":274.43}]},{"text":"Just fast enough to make up for your eyes.","show":277.3,"hide":280.4,"words":[{"text":"Just","start":277.3},{"text":"fast","start":277.541},{"text":"enough","start":277.782},{"text":"to","start":278.023},{"text":"make","start":278.264},{"text":"up","start":278.506},{"text":"for","start":278.747},{"text":"your","start":278.988},{"text":"eyes.","start":279.229}]}]},{"id":"runout","n":24,"section":3,"title":false,"first":282.8,"end":290.9,"caps":[{"text":"But that light is running out.","show":282.8,"hide":285.3,"words":[{"text":"But","start":282.8},{"text":"that","start":283.092},{"text":"light","start":283.383},{"text":"is","start":283.675},{"text":"running","start":283.967},{"text":"out.","start":284.258}]},{"text":"Every second, faster light swallows a longer stretch of its own past.","show":286.7,"hide":290.9,"words":[{"text":"Every","start":286.7},{"text":"second,","start":286.945},{"text":"faster","start":287.19},{"text":"light","start":287.435},{"text":"swallows","start":287.68},{"text":"a","start":287.925},{"text":"longer","start":288.17},{"text":"stretch","start":288.415},{"text":"of","start":288.66},{"text":"its","start":288.905},{"text":"own","start":289.15},{"text":"past.","start":289.395}]}]},{"id":"saturn","n":25,"section":3,"title":false,"first":293.9,"end":302.15,"caps":[{"text":"9:07 PM. Saturn goes out.","show":293.9,"hide":296.15,"words":[{"text":"9:07","start":293.9},{"text":"PM.","start":294.215},{"text":"Saturn","start":294.53},{"text":"goes","start":294.845},{"text":"out.","start":295.16}]},{"text":"Its light was sunlight that left before 9:00. It has all arrived.","show":297.95,"hide":302.15,"words":[{"text":"Its","start":297.95},{"text":"light","start":298.195},{"text":"was","start":298.44},{"text":"sunlight","start":298.685},{"text":"that","start":298.93},{"text":"left","start":299.175},{"text":"before","start":299.42},{"text":"9:00.","start":299.665},{"text":"It","start":299.91},{"text":"has","start":300.155},{"text":"all","start":300.4},{"text":"arrived.","start":300.645}]}]},{"id":"nearest","n":26,"section":3,"title":false,"first":305.75,"end":319.05,"caps":[{"text":"9:23 PM. Light is 1.4 million times faster.","show":305.75,"hide":308.9,"words":[{"text":"9:23","start":305.75},{"text":"PM.","start":306.026},{"text":"Light","start":306.301},{"text":"is","start":306.577},{"text":"1.4","start":306.853},{"text":"million","start":307.128},{"text":"times","start":307.404},{"text":"faster.","start":307.679}]},{"text":"The nearest star just went out.","show":311.7,"hide":314.25,"words":[{"text":"The","start":311.7},{"text":"nearest","start":311.998},{"text":"star","start":312.295},{"text":"just","start":312.593},{"text":"went","start":312.89},{"text":"out.","start":313.188}]},{"text":"The rest will follow, nearest first.","show":316.25,"hide":319.05,"words":[{"text":"The","start":316.25},{"text":"rest","start":316.577},{"text":"will","start":316.903},{"text":"follow,","start":317.23},{"text":"nearest","start":317.557},{"text":"first.","start":317.883}]}]},{"id":"question","n":27,"section":3,"title":false,"first":321.45,"end":324.5,"caps":[{"text":"What will be the last light you ever see?","show":321.45,"hide":324.5,"words":[{"text":"What","start":321.45},{"text":"will","start":321.687},{"text":"be","start":321.924},{"text":"the","start":322.162},{"text":"last","start":322.399},{"text":"light","start":322.636},{"text":"you","start":322.873},{"text":"ever","start":323.111},{"text":"see?","start":323.348}]}]}]};
